#!/usr/bin/env node
/**
 * Reads src/generated/openapi.json and emits src/generated/schemas.ts with a
 * flat `export type X = components["schemas"]["X"];` line per schema.
 *
 * Rationale: openapi-typescript emits a nested `components.schemas.*` shape,
 * so you can't `export *` the generated file to get flat type names. This
 * script generates the re-exports mechanically so callers can import API
 * types by their exact wire name (e.g. `GameResponse`) without us having
 * to hand-maintain a 200+ line re-export block in api.ts.
 *
 * Run via `npm run openapi:schemas` (or implicitly via `npm run openapi:gen`).
 */

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, "..");
const INPUT = resolve(REPO_ROOT, "src/generated/openapi.json");
const OUTPUT = resolve(REPO_ROOT, "src/generated/schemas.ts");

const spec = JSON.parse(readFileSync(INPUT, "utf8"));
const schemas = spec?.components?.schemas;
if (!schemas || typeof schemas !== "object") {
  console.error("No components.schemas found in", INPUT);
  process.exit(1);
}

const names = Object.keys(schemas).sort();
const validIdentifier = /^[A-Za-z_$][A-Za-z0-9_$]*$/;

const bad = names.filter((n) => !validIdentifier.test(n));
if (bad.length > 0) {
  console.error("Schema names that aren't valid TS identifiers:", bad);
  process.exit(1);
}

const lines = [
  "// This file is auto-generated by scripts/generate-schema-exports.mjs.",
  "// Source of truth: src/generated/openapi.json.",
  "// Do not edit by hand — run `npm run openapi:schemas` to regenerate.",
  "",
  'import type { components } from "./api";',
  "",
  'type Schemas = components["schemas"];',
  "",
];
for (const name of names) {
  lines.push(`export type ${name} = Schemas["${name}"];`);
}
lines.push("");

writeFileSync(OUTPUT, lines.join("\n"));
console.log(`Wrote ${names.length} schema exports to ${OUTPUT}`);
